INSERT INTO cms.case_studies (id, slug, status, sort_order, published_at, title, summary, client, service, category, description, challenge, tags, stats, seo_title, seo_description, image_key, image_alt, image_width, image_height, image_size, image_type)
VALUES ('01a1a5a3-ca7e-7b1f-be31-5d40a15bb776', 'royal-safari-tours', 'published', 0, '2026-11-04T08:18:58.339Z'::timestamptz, 'Royal Safari Tours', 'A tour website and booking dashboard for a Bangladesh travel company.', 'Royal Safari Tours', 'website-infrastructure', 'website-infrastructure', 'A full build of the Royal Safari Tours website with a custom admin dashboard behind it. Visitors browse tours in Bangladesh and abroad and send booking requests, while the team manages packages, bookings, hiring and site content in one place, without developer help.', 'Present premium tours clearly online and give the team one place to manage packages, bookings and content.', ARRAY['Next.js', 'Admin Dashboard', 'Booking Requests', 'PostgreSQL']::text[], '[{"label":"Tour packages online","value":"19"},{"label":"Countries with live packages","value":"5"},{"label":"Dashboard for the whole team","value":"1"},{"label":"Back-office modules","value":"4"}]'::jsonb, 'Royal Safari Tours: Travel Website Case Study', 'How AWTOMATIG built the Royal Safari Tours website and a custom admin dashboard for tour packages, booking requests, hiring and site content.', 'case-study/royal-safari-tours/image1.png', 'Royal Safari Tours website homepage', 1378, 1313, 2610556, 'image/png')
ON CONFLICT (slug) DO NOTHING;

