VALUES ('01a1a5a3-cec2-7c55-a130-40183fbe5e29', 'power-bank-bangladesh', 'published', 1, '2026-11-04T08:18:59.269Z'::timestamptz, 'Power Bank Bangladesh', 'A generator catalog with a dashboard for quotes, invoices and receipts.', 'PBB', 'back-office-operations', 'back-office-operations', 'A generator catalog site with a custom dashboard behind it. Visitors filter 98 models by brand and power, then request a quotation on WhatsApp, while the team manages products, prices, clients, quotations, invoices and money receipts, all as ready-to-send PDFs, without developer help.', 'Show a 98-model generator catalog clearly and let the team manage products, quotes and invoices on its own.', ARRAY['Next.js', 'PocketBase', 'PDF Generation', 'Admin Dashboard']::text[], '[{"label":"Generator models listed","value":"98"},{"label":"Document types as PDFs","value":"3"},{"label":"kVA top of the range","value":"1500"},{"label":"Locations served","value":"2"}]'::jsonb, 'Power Bank Bangladesh: Generator Site Case Study', 'How AWTOMATIG built the Power Bank Bangladesh generator catalog with a custom dashboard for quotations, invoices, money receipts and PDF documents.', 'case-study/power-bank-bangladesh/image1.png', 'Power Bank Bangladesh website homepage', 1080, 1080, 311490, 'image/png')
ON CONFLICT (slug) DO NOTHING;

