VALUES ('01a1a5a3-d263-7df7-8feb-fd6c493eff74', 'new-york-clean-team', 'published', 3, '2026-11-04T08:19:01.073Z'::timestamptz, 'New York Clean Team', 'A commercial cleaning website with a CMS and quote and booking forms.', 'NYC Team', 'website-infrastructure', 'website-infrastructure', 'A full build of the New York Clean Team website with a custom CMS behind it. Visitors browse services and industries and request a quote or booking, while the team manages pages, blog posts and client reviews without developer help, with form and call tracking built in.', 'Win commercial clients across five boroughs and let the team keep services, pages and reviews up to date.', ARRAY['Next.js', 'MongoDB', 'CMS', 'Local SEO']::text[], '[{"label":"Pages managed in the CMS","value":"74"},{"label":"Boroughs served","value":"5"},{"label":"Industry pages","value":"5"},{"label":"Conversion events tracked","value":"4"}]'::jsonb, 'New York Clean Team: Cleaning Website Case Study', 'How AWTOMATIG built the New York Clean Team website with a custom CMS, quote and booking forms, local SEO and conversion tracking.', 'case-study/new-york-clean-team/image1.png', 'New York Clean Team website homepage', 551, 525, 305856, 'image/png')
